SELECT 
FROM main_order
WHERE buyer_id = #{buyerId} AND is_deleted = 0

    AND status = #{status}

ORDER BY created_at DESC
LIMIT #{offset}, #{size}

mapper.update:
UPDATE main_order
SET status = 'PAID', paid_at = #{paidAt}, updated_at = #{paidAt}
WHERE main_order_id = #{mainOrderId}
  AND status = 'PENDING_PAYMENT'
  AND is_deleted = 0
  AND NOT EXISTS (
      SELECT 1 FROM `order` o
      WHERE o.main_order_id = #{mainOrderId}
        AND o.is_deleted = 0
        AND o.status = 'PENDING_PAYMENT'
  )

UPDATE main_order
SET status = 'CANCELLED', updated_at = #{updatedAt}
WHERE main_order_id = #{mainOrderId} AND status = 'PENDING_PAYMENT' AND is_deleted = 0
